def linechart(x,y,w,h,values,labels,maxv=100,fill=True,second=None,ticks=4):
 # SVG chart with deliberately discrete data and labelled points.
 l=70;r=50;top=35;bot=40;pw=w-l-r;phh=h-top-bot;pts=[(l+pw*.12+i*pw*.76/(len(values)-1),top+(1-v/maxv)*phh) for i,v in enumerate(values)]
 o=f'<svg xmlns="http://www.w3.org/2000/svg" style="position:absolute;left:{x}px;top:{y}px" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><defs><linearGradient id="g{x}{y}" x2="0" y2="1"><stop stop-color="#7b8bf0" stop-opacity=".6"/><stop offset="1" stop-color="#7b8bf0" stop-opacity=".05"/></linearGradient></defs>'
 for i in range(ticks+1):
  yy=top+i*phh/ticks;o+=f'<path d="M{l} {yy}H{w-r}" stroke="#c5c8cd" stroke-width="1"/><text x="{l-8}" y="{yy+5}" text-anchor="end" font-size="14" fill="#35383c">{maxv-i*maxv/ticks:g}</text>'
 for idx,vs in enumerate([second,values] if second else [values]):
  p=[(l+pw*.12+i*pw*.76/(len(vs)-1),top+(1-v/maxv)*phh) for i,v in enumerate(vs)];col='#a0dafa' if second and idx==0 else BLUE
  if fill:o+=f'<path d="M{p[0][0]} {h-bot} '+''.join(f'L{a} {b}' for a,b in p)+f'L{p[-1][0]} {h-bot}Z" fill="{col}" opacity=".3"/>'
  o+=f'<polyline points="'+ ' '.join(f'{a},{b}' for a,b in p)+f'" fill="none" stroke="{col}" stroke-width=".7"/>'
  for (a,b),v in zip(p,vs):o+=f'<circle cx="{a}" cy="{b}" r="3.5" fill="{col}"/><text x="{a}" y="{b-13}" text-anchor="middle" font-size="14" fill="{col}">{v}</text>'
 for i,lab in enumerate(labels):o+=f'<text x="{pts[i][0]}" y="{h-13}" text-anchor="middle" font-size="14" fill="#34383a">{lab}</text>'
 return o+'</svg>'
def bars(x,y,w,h,values,labels,maxv=100,alternate=False,gradient=False):
 l=35;bot=36;top=18;pw=w-l-10;phh=h-top-bot;n=len(values);bw=pw/n*.65
 s=f'<svg xmlns="http://www.w3.org/2000/svg" style="position:absolute;left:{x}px;top:{y}px" width="{w}" height="{h}"><defs><linearGradient id="bar{x}" x2="0" y2="1"><stop stop-color="#2344ee"/><stop offset="1" stop-color="#dbe0f9"/></linearGradient><linearGradient id="grey{x}" x2="0" y2="1"><stop stop-color="#bfc2d2"/><stop offset="1" stop-color="#f8fbfd"/></linearGradient></defs>'
 for i,v in enumerate(values):
  xx=l+(i+.5)*pw/n-bw/2;hh=v/maxv*phh;yy=h-bot-hh;color=(f'url(#bar{x})' if i==n-1 else f'url(#grey{x})') if gradient else (BLUE if not alternate or i%2==0 else '#dfe2e7')
  s+=f'<rect x="{xx}" y="{yy}" width="{bw}" height="{hh}" rx="{0 if gradient else 13}" fill="{color}"/><text x="{xx+bw/2}" y="{yy-8 if not gradient else yy+60}" text-anchor="middle" font-size="{36 if gradient else 14}" fill="{BLUE if not gradient else "#fff"}">{str(v)+"%" if gradient and i==n-1 else str(v) if not gradient else ""}</text><text x="{xx+bw/2}" y="{h-10}" text-anchor="middle" font-size="16" font-weight="600" fill="{BLUE if i==n-1 else TEXT}">{labels[i]}</text>'
 return s+'</svg>'
def pie(x,y,d,vals,donut=False,colors=None):
 import math
 colors=colors or [BLUE,'#93b8fa','#d7dcef'];cur=-90;out=f'<svg xmlns="http://www.w3.org/2000/svg" style="position:absolute;left:{x}px;top:{y}px" width="{d}" height="{d}" viewBox="0 0 {d} {d}">';c=d/2;r=d/2
 for i,v in enumerate(vals):
  end=cur+v*3.6;a=c+r*math.cos(math.radians(cur));b=c+r*math.sin(math.radians(cur));aa=c+r*math.cos(math.radians(end));bb=c+r*math.sin(math.radians(end));out+=f'<path d="M{c},{c}L{a},{b}A{r},{r} 0 {1 if v>50 else 0} 1 {aa},{bb}Z" fill="{colors[i]}"/>';mid=(cur+end)/2;rr=r*(.68 if donut else .56);tx=c+rr*math.cos(math.radians(mid));ty=c+rr*math.sin(math.radians(mid));out+=f'<text x="{tx}" y="{ty+6}" text-anchor="middle" font-size="18" font-weight="700" fill="{TEXT if i==2 else "#fff" if i==0 or not donut else BLUE}">{v}%</text>';cur=end
 if donut:out+=f'<circle cx="{c}" cy="{c}" r="{r*.4}" fill="#f4f8fb"/>'
 return out+'</svg>'
